CREATE TABLE knowledge_articles(article_id uuid PRIMARY KEY,title varchar(180) NOT NULL,category varchar(80) NOT NULL,content_reference varchar(255) NOT NULL,published_at timestamptz,active boolean NOT NULL);
CREATE TABLE support_tickets(ticket_id uuid PRIMARY KEY,principal_account_id uuid NOT NULL,meter_id uuid NOT NULL,subject varchar(180) NOT NULL,message text NOT NULL,ticket_status varchar(30) NOT NULL,created_at timestamptz NOT NULL,resolved_at timestamptz,closed_at timestamptz);
CREATE TABLE technicians(technician_id uuid PRIMARY KEY,full_name varchar(120) NOT NULL,accreditation_code varchar(60) NOT NULL UNIQUE,specialty varchar(80) NOT NULL,email varchar(255) NOT NULL,phone varchar(30) NOT NULL,available boolean NOT NULL,active boolean NOT NULL);
CREATE TABLE ticket_replies(reply_id uuid PRIMARY KEY,ticket_id uuid NOT NULL REFERENCES support_tickets,author_account_id uuid NOT NULL,body text NOT NULL,posted_at timestamptz NOT NULL);
CREATE TABLE ticket_photos(photo_id uuid PRIMARY KEY,ticket_id uuid NOT NULL REFERENCES support_tickets,object_reference varchar(255) NOT NULL,uploaded_by_account_id uuid NOT NULL,uploaded_at timestamptz NOT NULL);
CREATE TABLE technical_visits(visit_id uuid PRIMARY KEY,ticket_id uuid NOT NULL REFERENCES support_tickets,requested_window_start timestamptz,requested_window_end timestamptz,visit_status varchar(30) NOT NULL,completed_at timestamptz);
CREATE TABLE technician_assignments(assignment_id uuid PRIMARY KEY,visit_id uuid NOT NULL REFERENCES technical_visits,technician_id uuid NOT NULL REFERENCES technicians,assigned_at timestamptz NOT NULL,active boolean NOT NULL);
CREATE TABLE visit_diagnoses(diagnosis_id uuid PRIMARY KEY,visit_id uuid NOT NULL UNIQUE REFERENCES technical_visits,summary text NOT NULL,final_cost numeric(10,2) NOT NULL,billing_reference_id uuid,created_at timestamptz NOT NULL);
CREATE TABLE service_ratings(rating_id uuid PRIMARY KEY,ticket_id uuid NOT NULL UNIQUE REFERENCES support_tickets,score integer NOT NULL CHECK(score BETWEEN 1 AND 5),comment text,rated_at timestamptz NOT NULL);
